--
-- Table structure for table `leave_requests`
--

DROP TABLE IF EXISTS `leave_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `leave_requests` (
  `leave_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `leave_type_id` int(11) NOT NULL,
  `school_year_id` int(10) unsigned DEFAULT NULL,
  `reason` text NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `total_days` decimal(5,2) NOT NULL DEFAULT 0.00,
  `status` enum('PENDING','APPROVED','REJECTED','PARTIALLY_APPROVED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `workflow_status` enum('PENDING_REVIEW','FORWARDED','RECORDED') NOT NULL DEFAULT 'PENDING_REVIEW',
  `admin_note` text DEFAULT NULL,
  `forwarded_at` datetime DEFAULT NULL,
  `forwarded_by` int(11) DEFAULT NULL,
  `is_backdated` tinyint(1) NOT NULL DEFAULT 0,
  `backdate_reason` text DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `is_attendance_recorded` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Admin has recorded principal decision in attendance (0=pending, 1=done)',
  `recorded_at` timestamp NULL DEFAULT NULL,
  `recorded_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`leave_id`),
  KEY `fk_leave_emp` (`employee_id`),
  KEY `fk_leave_type` (`leave_type_id`),
  KEY `fk_leave_approver` (`approved_by`),
  KEY `fk_lr_school_year` (`school_year_id`),
  CONSTRAINT `fk_leave_approver` FOREIGN KEY (`approved_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `fk_leave_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`employee_id`),
  CONSTRAINT `fk_leave_type` FOREIGN KEY (`leave_type_id`) REFERENCES `leave_types` (`leave_type_id`),
  CONSTRAINT `fk_lr_school_year` FOREIGN KEY (`school_year_id`) REFERENCES `school_years` (`school_year_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

