CREATE TABLE `payroll_workflow_log` (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  `period_id` int(11) NOT NULL,
  `event_type` enum('GENERATED','SUBMITTED','APPROVED','RETURNED','RELEASED') NOT NULL,
  `performed_by` int(11) NOT NULL,
  `performer_name` varchar(200) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `gross_total` decimal(12,2) DEFAULT NULL COMMENT 'Total gross pay at time of event',
  `net_total` decimal(12,2) DEFAULT NULL COMMENT 'Total net pay at time of event',
  `emp_count` int(11) DEFAULT NULL COMMENT 'Employee count at time of event',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`log_id`),
  KEY `fk_pwl_user` (`performed_by`),
  KEY `idx_pwl_period` (`period_id`),
  KEY `idx_pwl_type` (`event_type`),
  CONSTRAINT `fk_pwl_period` FOREIGN KEY (`period_id`) REFERENCES `payroll_periods` (`period_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pwl_user` FOREIGN KEY (`performed_by`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
